            "source": "{لاتجعلوا بيوتكم مقابر، إنّ الشّيطان ينفر من البيت الذي تقرأ فيه سورة البقرة} رواه مسلم 1/ 539. ومما يطرد الشّيطان أذكار الصّباح والمساء، والنّوم والاستيقاظ، وغير ذلك من الأذكار المشروعة مثل قراءة آية الكرسيّ عند النّوم، والآيتين الأخيرتين من سورة البقرة، ومن قال: لا إله إلّا اللّه وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير مائة مرة كانت له حِرْزًا من الشّيطان يومه كلّه. وكذا الأذان يطرد الشّيطان",
