            "text": "ما يقول إذا دخل على أهله: «تَوْبًا تَوْبًا، لِرَبِّنَا أَوْبًا، لَا يُغَادِرُ حَوْبًا (أَيْ نَسْتَغْفِرُكَ رَبَّنَا تَوْبَةً لَا تَبْقَى مَعَهَا ذَنْبٌ)»",
